// Core tests: the 8 literal core cases from the fixed spec's
// fixtures.json (vendored verbatim at test/fixtures.json from spec
// candidate a536732ba0512afc595c924b242ee220211bf7ed; expected values
// taken verbatim, never generated by the product), plus hand-derived
// base-table, invariant, validation-order, and report-serialization
// cases. The SPEC's own rules are the oracle; every extra expected
// value below was computed by hand from those rules.

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import test from "node:test";
import { buildReport, run } from "../public/js/core/boxes.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const PLAIN = {
  manyBooks: false,
  largeKitchen: false,
  manyClothes: false,
  fragileItems: false,
  livedOver5Years: false,
};

// Hand-derived base table: all five home types with every toggle off.
// small = ceil(B*30%), medium = ceil(B*50%), large = B - small - medium,
// tape = paper = ceil(total/10).
const BASE_TABLE = [
  ["studio", 15, { small: 5, medium: 8, large: 2 }, 2],
  ["one-bedroom", 25, { small: 8, medium: 13, large: 4 }, 3],
  ["two-bedroom", 40, { small: 12, medium: 20, large: 8 }, 4],
  ["three-bedroom", 60, { small: 18, medium: 30, large: 12 }, 6],
  ["four-bedroom", 80, { small: 24, medium: 40, large: 16 }, 8],
];
for (const [homeType, baseBoxes, split, rolls] of BASE_TABLE) {
  test(`hand-derived base table: ${homeType}`, () => {
    assert.deepEqual(run({ homeType, ...PLAIN }), {
      ok: true,
      result: {
        homeType,
        baseBoxes,
        baseSplit: split,
        adders: { manyBooks: 0, largeKitchen: 0, manyClothes: 0, fragileItems: 0 },
        upliftBoxes: 0,
        totalBoxes: baseBoxes,
        boxes: split,
        supplies: { tapeRolls: rolls, packingPaperRolls: rolls },
      },
    });
  });
}

// Independent recomputation straight from the SPEC's prose (ceiling
// percentages, adders before the uplift, uplift all medium, one roll
// per 10 boxes rounded up) — a separate formulation from the core's
// floor((x + 99) / 100) arithmetic.
function expectedFromSpec(input) {
  const B = { studio: 15, "one-bedroom": 25, "two-bedroom": 40, "three-bedroom": 60, "four-bedroom": 80 }[input.homeType];
  const small = Math.ceil((B * 30) / 100);
  const medium = Math.ceil((B * 50) / 100);
  const large = B - small - medium;
  const adders = {
    manyBooks: input.manyBooks ? 8 : 0,
    largeKitchen: input.largeKitchen ? 6 : 0,
    manyClothes: input.manyClothes ? 5 : 0,
    fragileItems: input.fragileItems ? 4 : 0,
  };
  const subtotal = B + adders.manyBooks + adders.largeKitchen + adders.manyClothes + adders.fragileItems;
  const upliftBoxes = input.livedOver5Years ? Math.ceil(subtotal / 5) : 0;
  const totalBoxes = subtotal + upliftBoxes;
  const tapeRolls = Math.ceil(totalBoxes / 10);
  return {
    ok: true,
    result: {
      homeType: input.homeType,
      baseBoxes: B,
      baseSplit: { small, medium, large },
      adders,
      upliftBoxes,
      totalBoxes,
      boxes: {
        small: small + adders.manyBooks + adders.fragileItems,
        medium: medium + adders.largeKitchen + adders.manyClothes + upliftBoxes,
        large,
      },
      supplies: { tapeRolls, packingPaperRolls: tapeRolls + (input.fragileItems ? 1 : 0) },
    },
  };
}

test("invariant sweep: all 5 home types x all 32 toggle combinations", () => {
  const toggleNames = ["manyBooks", "largeKitchen", "manyClothes", "fragileItems", "livedOver5Years"];
  for (const homeType of ["studio", "one-bedroom", "two-bedroom", "three-bedroom", "four-bedroom"]) {
    for (let mask = 0; mask < 32; mask += 1) {
      const input = { homeType };
      toggleNames.forEach((name, index) => {
        input[name] = (mask & (1 << index)) !== 0;
      });
      const actual = run(input);
      assert.deepEqual(actual, expectedFromSpec(input), `${homeType} mask ${mask}`);
      const { boxes, totalBoxes } = actual.result;
      assert.equal(boxes.small + boxes.medium + boxes.large, totalBoxes);
    }
  }
});

// Validation classes and the pinned order: capacity, structure/types
// (field order), UNICODE, EMPTY, ENUM.
test("extra field and missing field are SCHEMA with field null", () => {
  assert.deepEqual(run({ homeType: "studio", ...PLAIN, extra: 1 }), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  const missing = { homeType: "studio", ...PLAIN };
  delete missing.manyBooks;
  assert.deepEqual(run(missing), { ok: false, error: { code: "SCHEMA", field: null, row: null } });
  assert.deepEqual(run(null), { ok: false, error: { code: "SCHEMA", field: null, row: null } });
  assert.deepEqual(run(["studio"]), { ok: false, error: { code: "SCHEMA", field: null, row: null } });
});

test("accessor properties are SCHEMA (field reads use descriptors only)", () => {
  // The capacity step measures the SPEC's own JSON serialization; the
  // field validation itself reads own data descriptors and rejects any
  // accessor as SCHEMA without using its value.
  const hostile = { ...PLAIN };
  Object.defineProperty(hostile, "homeType", {
    enumerable: true,
    get() {
      return "studio";
    },
  });
  assert.deepEqual(run(hostile), { ok: false, error: { code: "SCHEMA", field: null, row: null } });
});

test("wrong field types are SCHEMA on the first bad field in field order", () => {
  assert.deepEqual(run({ homeType: 42, ...PLAIN }), {
    ok: false,
    error: { code: "SCHEMA", field: "homeType", row: null },
  });
  assert.deepEqual(run({ homeType: "studio", ...PLAIN, largeKitchen: 1 }), {
    ok: false,
    error: { code: "SCHEMA", field: "largeKitchen", row: null },
  });
  // Type checks (step 2) precede the homeType value checks (steps 3-5),
  // so a bad toggle beats an out-of-enum or empty home type.
  assert.deepEqual(run({ homeType: "five-bedroom", ...PLAIN, manyBooks: "yes" }), {
    ok: false,
    error: { code: "SCHEMA", field: "manyBooks", row: null },
  });
  assert.deepEqual(run({ homeType: "", ...PLAIN, fragileItems: "no" }), {
    ok: false,
    error: { code: "SCHEMA", field: "fragileItems", row: null },
  });
});

test("lone surrogate, empty, and oversized home types", () => {
  assert.deepEqual(run({ homeType: "\uD800", ...PLAIN }), {
    ok: false,
    error: { code: "UNICODE", field: "homeType", row: null },
  });
  assert.deepEqual(run({ homeType: "", ...PLAIN }), {
    ok: false,
    error: { code: "EMPTY", field: "homeType", row: null },
  });
  // 70,000 characters serialize to more than 65,536 bytes: capacity is
  // checked before structure and values.
  assert.deepEqual(run({ homeType: "a".repeat(70000), ...PLAIN }), {
    ok: false,
    error: { code: "INPUT_LIMIT", field: null, row: null },
  });
});

// Report serialization: canonical bytes written out by hand from the
// SPEC's rule (keys sorted by UTF-16 code units recursively, compact,
// one trailing LF). The SHA-256 is taken over this literal, not over
// anything the product produced.
const STUDIO_REPORT_TEXT =
  '{"adders":{"fragileItems":0,"largeKitchen":0,"manyBooks":0,"manyClothes":0},' +
  '"baseBoxes":15,"baseSplit":{"large":2,"medium":8,"small":5},' +
  '"boxes":{"large":2,"medium":8,"small":5},"homeType":"studio",' +
  '"supplies":{"packingPaperRolls":2,"tapeRolls":2},"totalBoxes":15,"upliftBoxes":0}\n';

test("report bytes are the canonical serialization of the result", () => {
  const { result } = run({ homeType: "studio", ...PLAIN });
  const report = buildReport(result);
  assert.equal(report.ok, true);
  assert.equal(report.filename, "moving-box-estimator-report.json");
  assert.equal(report.text, STUDIO_REPORT_TEXT);
  assert.equal(
    createHash("sha256").update(report.text, "utf8").digest("hex"),
    createHash("sha256").update(STUDIO_REPORT_TEXT, "utf8").digest("hex"),
  );
  // Key order of the input object does not matter: the serializer sorts.
  const shuffled = {
    upliftBoxes: 0,
    totalBoxes: 15,
    supplies: { tapeRolls: 2, packingPaperRolls: 2 },
    homeType: "studio",
    boxes: { small: 5, medium: 8, large: 2 },
    baseSplit: { small: 5, medium: 8, large: 2 },
    baseBoxes: 15,
    adders: { manyClothes: 0, manyBooks: 0, largeKitchen: 0, fragileItems: 0 },
  };
  assert.equal(buildReport(shuffled).text, STUDIO_REPORT_TEXT);
});
